struct VSOut
{
    float4 pos : SV_POSITION;
    float2 uv  : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    float2 uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(uv * 2.0 - 1.0, 0.0, 1.0);
    o.uv = uv;
    o.uv.y = 1.0 - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut
{
    float4 pos : SV_POSITION;
    float2 uv  : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;

    float3 bg = float3(0.1, 0.1, 0.15);

    float4 layer1 = float4(0.8, 0.2, 0.2, 0.0);
    float2 c1 = float2(0.35 + 0.1 * sin(t), 0.5);
    float d1 = length(uv - c1);
    if (d1 < 0.25) layer1.a = 0.6 * smoothstep(0.25, 0.15, d1);

    float4 layer2 = float4(0.2, 0.7, 0.3, 0.0);
    float2 c2 = float2(0.5, 0.5 + 0.1 * cos(t * 1.3));
    float d2 = length(uv - c2);
    if (d2 < 0.25) layer2.a = 0.6 * smoothstep(0.25, 0.15, d2);

    float4 layer3 = float4(0.2, 0.3, 0.9, 0.0);
    float2 c3 = float2(0.65 - 0.1 * sin(t * 0.8), 0.5);
    float d3 = length(uv - c3);
    if (d3 < 0.25) layer3.a = 0.6 * smoothstep(0.25, 0.15, d3);

    float3 color = bg;
    color = lerp(color, layer1.rgb, layer1.a);
    color = lerp(color, layer2.rgb, layer2.a);
    color = lerp(color, layer3.rgb, layer3.a);

    float alpha = saturate(layer1.a + layer2.a + layer3.a);
    return float4(color, max(alpha, 0.3));
}
